class VSS_Text(spec("common")):
    @property
    def version(self):
        return "26.0.0"

    @property
    def tarball(self):
        return "vss-text-%s.zip" % self.version

    @property
    def source_pkg_build(self):
        return [
            self.HTTPSSourceBuilder(
                name=self.tarball,
                url="https://github.com/AdaCore/vss-text/archive/refs/tags/v%s.zip"
                % self.version,
            )
        ]

    @property
    def build_source_list(self):
        return [Anod.Source(name=self.tarball, publish=True, dest="")]

    @property
    def build_deps(self):
        return [
            Anod.Dependency("base_gcc", track=True),
            Anod.Dependency("gprbuild", track=True),
        ]

    @Anod.primitive()
    def build(self):
        for m in self.deps:
            self.deps[m].setenv()

        text_replace(
            os.path.join(
                self["SRC_DIR"],
                "source",
                "text",
                "implementation",
                "vss-strings-cursors-iterators-characters.adb",
            ),
            [
                (
                    "package body VSS.Strings.Cursors.Iterators.Characters is",
                    "pragma Ada_2022;\npackage body VSS.Strings.Cursors.Iterators.Characters is",
                )
            ],
        )

        build_profile = "release"
        build_mode = "prod"
        gpr_files = [
            os.path.join(self["SRC_DIR"], gpr)
            for gpr in (
                "gnat/vss_gnat.gpr",
                "gnat/vss_text.gpr",
            )
        ]

        for library_type in ["static"]:
            for gpr in gpr_files:
                self.shell(
                    "gprbuild",
                    "-p",
                    "-P",
                    gpr,
                    "-j" + str(self.jobs),
                    "--relocate-build-tree=" + library_type,
                    "-XLIBRARY_TYPE=" + library_type,
                    "-XBUILD_PROFILE=" + build_profile,
                )

            for gpr in gpr_files:
                self.shell(
                    "gprinstall",
                    "-f",
                    "-p",
                    "-P",
                    gpr,
                    "--relocate-build-tree=" + library_type,
                    "--prefix=" + self["INSTALL_DIR"],
                    "-XBUILD_MODE=" + build_mode,
                    "-XBUILD_PROFILE=" + build_profile,
                    "-XLIBRARY_TYPE=" + library_type,
                    "--build-var=LIBRARY_TYPE",
                    "--build-name=" + library_type,
                )

        self.clean()

